WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_rank_direct'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '直接比较', 'kp-xingce-data-rank-direct', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "直接比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不涉及任何公式，只需将材料里的原始数据排序。本质是量级和有效数字的比对。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“2023年各项指标按从大到小排序，正确的是？”。数据全在材料里明晃晃地写着。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心判断法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 看量级（位数与单位）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 先数位数。5位数永远大于4位数。如果材料的单位有不同（如亿元 vs 万元），必须先统一单位。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 比数字（从左向右）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 量级相同时，从左边最高位开始比对，首位决出胜负即停止。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看选项ABCD涉及了哪些主体] --> B[只在材料中找这几个主体的原始数据]\nB --> C{这几个数据的单位和量级是否统一?}\nC -- 否 --> D[统一量级(如把亿元补零变万元)]\nC -- 是 --> E[从左往右按位比较数值大小]\nD --> E\nE --> F[得出最大或最小项, 对照选项排除干扰]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年产值：甲为8450亿，乙为2.1万亿，丙为985亿，丁为6000亿。由大到小排序正确的是？选项：A. 甲>乙>丁>丙  B. 乙>甲>丁>丙  C. 乙>甲>丙>丁  D. 甲>丁>丙>乙"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "统一量级：乙是 2.1 万亿 = 21000 亿。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比量级位数：乙是 5位数(21000)，甲(8450)、丙(985)、丁(6000) 都是 4位数以内。所以 乙 最大！直接排除 A 和 D。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比具体数值：剩下 甲(8450), 丁(6000), 丙(985)。看首位，8 > 6 > 0(不到千位)。所以 甲 > 丁 > 丙。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排雷：全盘排序综合症", "marks": [{"type": "bold"}]}, {"type": "text", "text": "表格里有 15 个省份的数据，让你排前三名。千万不要在草稿纸上把 15 个省份全排一遍！看看 ABCD 四个选项，通常只涉及 4 到 5 个省份。一切以选项为导向，只排选项里出现的主体！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "强化自己的“找选项特征”能力。凡是排序题，先扫一眼选项的第一个元素和最后一个元素，只要把最大值和最小值找出来，题基本就解了。"}]}]}$$ AS jsonb), NULL, '直接比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "直接比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_direct", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
